*, *::before, *::after {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  background: #f5f7fa;
  color: #1f2933;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
  min-height: 100vh;
}

.board {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

h1 {
  font-size: 22px;
  font-weight: 600;
  margin: 0 0 16px;
  color: #102a43;
}

.task-form {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: flex-end;
  background: #ffffff;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  padding: 14px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.field span {
  font-size: 13px;
  color: #52606d;
}

.field input,
.field select {
  font: inherit;
  color: inherit;
  background: #ffffff;
  border: 1px solid #bcccdc;
  border-radius: 6px;
  padding: 8px 10px;
  min-height: 40px;
}

.field input {
  width: 100%;
}

.field:first-child {
  flex: 1 1 220px;
}

.field select {
  min-width: 96px;
}

.field input:focus,
.field select:focus,
button:focus-visible {
  outline: 2px solid #2f80ed;
  outline-offset: 1px;
}

button {
  font: inherit;
  cursor: pointer;
  border-radius: 6px;
  border: 1px solid #bcccdc;
  background: #ffffff;
  color: #1f2933;
  padding: 8px 14px;
  min-height: 40px;
}

button:hover {
  background: #f0f4f8;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

#add-button {
  background: #2f80ed;
  border-color: #2f80ed;
  color: #ffffff;
  font-weight: 600;
}

#add-button:hover {
  background: #1c6dd0;
}

.error {
  margin: 10px 0 0;
  padding: 8px 12px;
  background: #fdecea;
  border: 1px solid #f5c2c0;
  border-radius: 6px;
  color: #b42318;
  font-size: 14px;
  word-break: break-word;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  margin: 16px 0 12px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.filter {
  padding: 6px 12px;
  min-height: 36px;
  font-size: 14px;
}

.filter.active {
  background: #e3f0ff;
  border-color: #2f80ed;
  color: #1c6dd0;
  font-weight: 600;
}

.status {
  margin: 0;
  font-size: 13px;
  color: #52606d;
  min-height: 1.5em;
}

.status.is-error {
  color: #b42318;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.task-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  background: #ffffff;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  padding: 10px 12px;
}

.task-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 200px;
  min-width: 0;
  cursor: pointer;
}

.task-toggle input {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  margin: 0;
  cursor: pointer;
}

.task-title {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.task-item.is-done .task-title {
  color: #829ab1;
  text-decoration: line-through;
}

.priority-badge {
  flex: 0 0 auto;
  font-size: 12px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid transparent;
}

.priority-3 {
  background: #fdecea;
  border-color: #f5c2c0;
  color: #b42318;
}

.priority-2 {
  background: #fff4e5;
  border-color: #f7d9a8;
  color: #8a5a00;
}

.priority-1 {
  background: #e8f5e9;
  border-color: #b7dfb9;
  color: #2e7d32;
}

.empty {
  margin: 16px 0 0;
  text-align: center;
  color: #829ab1;
  font-size: 14px;
}

@media (max-width: 480px) {
  .board {
    padding: 16px 12px 32px;
  }

  .task-form {
    padding: 12px;
  }

  .field:first-child {
    flex-basis: 100%;
  }

  #add-button {
    flex: 1 1 100%;
  }

  .toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
}

(function () {
  'use strict';

  var PRIORITY_LABELS = { 1: '低', 2: '中', 3: '高' };
  var VALID_FILTERS = ['all', 'true', 'false'];

  var form = document.getElementById('task-form');
  var titleInput = document.getElementById('title-input');
  var prioritySelect = document.getElementById('priority-select');
  var addButton = document.getElementById('add-button');
  var formError = document.getElementById('form-error');
  var saveStatus = document.getElementById('save-status');
  var taskList = document.getElementById('task-list');
  var emptyHint = document.getElementById('empty-hint');
  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('.filter'));

  var currentFilter = 'all';
  var loading = false;

  function showError(message) {
    formError.textContent = message;
    formError.hidden = false;
  }

  function clearError() {
    formError.textContent = '';
    formError.hidden = true;
  }

  function setStatus(message, isError) {
    saveStatus.textContent = message;
    if (isError) {
      saveStatus.classList.add('is-error');
    } else {
      saveStatus.classList.remove('is-error');
    }
  }

  function setBusy(busy) {
    loading = busy;
    addButton.disabled = busy;
    filterButtons.forEach(function (btn) {
      btn.disabled = busy;
    });
  }

  function readJson(response) {
    return response.json().catch(function () {
      return null;
    });
  }

  function errorMessageFrom(data, fallback) {
    if (data && typeof data.error === 'string' && data.error) {
      return data.error;
    }
    return fallback;
  }

  function renderTasks(tasks) {
    taskList.textContent = '';
    tasks.forEach(function (task) {
      var item = document.createElement('li');
      item.className = 'task-item' + (task.done ? ' is-done' : '');
      item.setAttribute('data-id', String(task.id));

      var label = document.createElement('label');
      label.className = 'task-toggle';

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.done === true;
      checkbox.setAttribute('aria-label', '标记完成：' + task.title);
      checkbox.addEventListener('change', function () {
        toggleTask(task, checkbox);
      });

      var title = document.createElement('span');
      title.className = 'task-title';
      title.textContent = task.title;

      label.appendChild(checkbox);
      label.appendChild(title);

      var badge = document.createElement('span');
      badge.className = 'priority-badge priority-' + String(task.priority);
      badge.textContent = '优先级：' + (PRIORITY_LABELS[task.priority] || String(task.priority));

      item.appendChild(label);
      item.appendChild(badge);
      taskList.appendChild(item);
    });
    emptyHint.hidden = tasks.length > 0;
  }

  function loadTasks() {
    if (loading) {
      return;
    }
    setBusy(true);
    setStatus('加载中…', false);
    var url = '/api/tasks?done=' + encodeURIComponent(currentFilter);
    fetch(url, { method: 'GET', headers: { Accept: 'application/json' } })
      .then(function (response) {
        return readJson(response).then(function (data) {
          if (!response.ok) {
            throw new Error(errorMessageFrom(data, '加载失败（HTTP ' + response.status + '）'));
          }
          if (!Array.isArray(data)) {
            throw new Error('加载失败：返回数据格式不正确');
          }
          return data;
        });
      })
      .then(function (tasks) {
        renderTasks(tasks);
        setStatus('已加载', false);
      })
      .catch(function (err) {
        setStatus('加载失败', true);
        showError(err && err.message ? err.message : '加载失败');
      })
      .then(function () {
        setBusy(false);
      });
  }

  function validateForm() {
    var title = titleInput.value.trim();
    if (title.length < 1 || title.length > 80) {
      return { error: '标题去除两端空白后需为 1 至 80 个字符' };
    }
    var priority = Number(prioritySelect.value);
    if (priority !== 1 && priority !== 2 && priority !== 3) {
      return { error: '请选择有效的优先级' };
    }
    return { title: title, priority: priority };
  }

  function createTask(event) {
    event.preventDefault();
    if (loading) {
      return;
    }
    clearError();
    var result = validateForm();
    if (result.error) {
      showError(result.error);
      setStatus('保存失败', true);
      return;
    }

    setBusy(true);
    setStatus('保存中…', false);
    fetch('/api/tasks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ title: result.title, priority: result.priority })
    })
      .then(function (response) {
        return readJson(response).then(function (data) {
          if (!response.ok) {
            throw new Error(errorMessageFrom(data, '保存失败（HTTP ' + response.status + '）'));
          }
          return data;
        });
      })
      .then(function () {
        titleInput.value = '';
        setStatus('已保存', false);
        setBusy(false);
        loadTasks();
      })
      .catch(function (err) {
        setStatus('保存失败', true);
        showError(err && err.message ? err.message : '保存失败');
        setBusy(false);
      });
  }

  function toggleTask(task, checkbox) {
    if (loading) {
      checkbox.checked = task.done === true;
      return;
    }
    clearError();
    setBusy(true);
    setStatus('保存中…', false);
    fetch('/api/tasks/' + encodeURIComponent(String(task.id)), {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ done: !task.done })
    })
      .then(function (response) {
        return readJson(response).then(function (data) {
          if (!response.ok) {
            throw new Error(errorMessageFrom(data, '保存失败（HTTP ' + response.status + '）'));
          }
          return data;
        });
      })
      .then(function () {
        setStatus('已保存', false);
        setBusy(false);
        loadTasks();
      })
      .catch(function (err) {
        checkbox.checked = task.done === true;
        setStatus('保存失败', true);
        showError(err && err.message ? err.message : '保存失败');
        setBusy(false);
      });
  }

  function selectFilter(button) {
    var value = button.getAttribute('data-filter');
    if (VALID_FILTERS.indexOf(value) === -1 || value === currentFilter) {
      return;
    }
    currentFilter = value;
    filterButtons.forEach(function (btn) {
      var active = btn === button;
      btn.classList.toggle('active', active);
      btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
    clearError();
    loadTasks();
  }

  form.addEventListener('submit', createTask);
  titleInput.addEventListener('input', function () {
    if (!formError.hidden) {
      clearError();
    }
  });
  filterButtons.forEach(function (btn) {
    btn.setAttribute('aria-pressed', btn.classList.contains('active') ? 'true' : 'false');
    btn.addEventListener('click', function () {
      selectFilter(btn);
    });
  });

  loadTasks();
})();

